using System;
using System.Collections.Generic;

namespace Framework.AI.Actions
{
    /// <summary>
    /// エージェントの行動実行と状態遷移を管理する。
    /// </summary>
    /// <typeparam name="TAction">行動識別子の型</typeparam>
    /// <typeparam name="TContext">行動実行情報の型</typeparam>
    /// <remarks>
    /// 1つのエージェントにつき1つ生成する。
    /// 時間はTickによって進行する。
    /// コールバック中の再入操作は許可しない。
    /// </remarks>
    public sealed class AgentActionController<TAction, TContext>
    {
        /// <summary>
        /// 登録された行動。
        /// </summary>
        private readonly Dictionary<
            TAction, IAgentAction<TAction, TContext>> actions =
                new Dictionary<
                    TAction, IAgentAction<TAction, TContext>>();

        /// <summary>
        /// 各行動のクールダウン終了時刻。
        /// </summary>
        private readonly Dictionary<TAction, double>
            cooldownEndTimes =
                new Dictionary<TAction, double>();

        /// <summary>
        /// 現在実行中の行動。
        /// </summary>
        private IAgentAction<TAction, TContext> currentAction;

        /// <summary>
        /// コントローラーの累積経過時間。
        /// </summary>
        private double totalElapsedTime;

        /// <summary>
        /// 現在の行動の経過時間。
        /// </summary>
        private double actionElapsedTime;

        /// <summary>
        /// 行動処理またはイベント通知中かどうか。
        /// </summary>
        private bool isProcessing;

        /// <summary>
        /// 一時停止中かどうか。
        /// </summary>
        private bool isPaused;

        /// <summary>
        /// 登録されている行動数。
        /// </summary>
        public int Count => actions.Count;

        /// <summary>
        /// 行動を実行中かどうか。
        /// </summary>
        public bool HasCurrentAction => currentAction != null;

        /// <summary>
        /// 現在実行中の行動。
        /// 行動が存在しない場合はnull。
        /// </summary>
        public IAgentAction<TAction, TContext>
            CurrentAction => currentAction;

        /// <summary>
        /// 現在の行動の経過秒数。
        /// </summary>
        public double ActionElapsedTime => actionElapsedTime;

        /// <summary>
        /// コントローラーの累積経過秒数。
        /// </summary>
        public double TotalElapsedTime => totalElapsedTime;

        /// <summary>
        /// 一時停止中かどうか。
        /// </summary>
        public bool IsPaused => isPaused;

        /// <summary>
        /// 現在の行動を通常中断できるかどうか。
        /// </summary>
        public bool CanInterruptCurrent =>
            currentAction == null ||
            (currentAction.Settings.CanInterrupt &&
             actionElapsedTime >=
                currentAction.Settings.MinimumDuration);

        /// <summary>
        /// 行動が開始されたときに通知する。
        /// </summary>
        public event Action<TAction> ActionStarted;

        /// <summary>
        /// 行動が終了したときに通知する。
        /// </summary>
        public event Action<TAction, AgentActionExitReason>
            ActionEnded;

        /// <summary>
        /// 行動を登録する。
        /// </summary>
        /// <param name="action">登録する行動</param>
        /// <returns>登録に成功した場合はtrue</returns>
        public bool TryRegister(
            IAgentAction<TAction, TContext> action)
        {
            EnsureNotProcessing();

            if (action == null)
            {
                throw new ArgumentNullException(nameof(action));
            }

            if (action.Id is null || action.Settings == null)
            {
                throw new ArgumentException(
                    "行動識別子または設定が不正です。",
                    nameof(action));
            }

            if (actions.ContainsKey(action.Id))
            {
                return false;
            }

            actions.Add(action.Id, action);

            return true;
        }

        /// <summary>
        /// 指定された行動が登録されているか判定する。
        /// </summary>
        /// <param name="id">行動識別子</param>
        /// <returns>登録されている場合はtrue</returns>
        public bool HasAction(TAction id)
        {
            return !(id is null) &&
                   actions.ContainsKey(id);
        }

        /// <summary>
        /// 指定された行動を登録解除する。
        /// </summary>
        /// <param name="id">行動識別子</param>
        /// <returns>登録解除に成功した場合はtrue</returns>
        /// <remarks>
        /// 実行中の行動は登録解除できない。
        /// </remarks>
        public bool TryUnregister(TAction id)
        {
            EnsureNotProcessing();

            if (id is null)
            {
                return false;
            }

            if (currentAction != null &&
                EqualityComparer<TAction>.Default.Equals(
                    currentAction.Id, id))
            {
                return false;
            }

            if (!actions.Remove(id))
            {
                return false;
            }

            cooldownEndTimes.Remove(id);

            return true;
        }

        /// <summary>
        /// 現在の行動識別子を取得する。
        /// </summary>
        /// <param name="id">取得した行動識別子</param>
        /// <returns>行動を実行中の場合はtrue</returns>
        public bool TryGetCurrentActionId(out TAction id)
        {
            if (currentAction == null)
            {
                id = default(TAction);

                return false;
            }

            id = currentAction.Id;

            return true;
        }

        /// <summary>
        /// 指定された行動のクールダウン残り秒数を取得する。
        /// </summary>
        /// <param name="id">行動識別子</param>
        /// <returns>クールダウン残り秒数</returns>
        public float GetCooldownRemaining(TAction id)
        {
            if (id is null ||
                !cooldownEndTimes.TryGetValue(
                    id, out double endTime))
            {
                return 0f;
            }

            return (float)Math.Max(
                0d, endTime - totalElapsedTime);
        }

        /// <summary>
        /// 指定された行動がクールダウン中か判定する。
        /// </summary>
        /// <param name="id">行動識別子</param>
        /// <returns>クールダウン中の場合はtrue</returns>
        public bool IsOnCooldown(TAction id)
        {
            return GetCooldownRemaining(id) > 0f;
        }

        /// <summary>
        /// 指定された行動を開始または切り替える。
        /// </summary>
        /// <param name="id">開始する行動識別子</param>
        /// <param name="context">行動実行情報</param>
        /// <param name="forceInterrupt">
        /// 現在の行動の中断制限を無視するか。
        /// </param>
        /// <returns>要求した行動が実行中になった場合はtrue</returns>
        /// <remarks>
        /// 同一行動への要求では再初期化を行わない。
        /// 強制割り込みでも開始条件とクールダウンは維持する。
        /// </remarks>
        public bool TryStartAction(
            TAction id,
            TContext context,
            bool forceInterrupt = false)
        {
            EnsureNotProcessing();

            if (isPaused ||
                id is null ||
                !actions.TryGetValue(id, out var nextAction))
            {
                return false;
            }

            // 同じ行動を再要求しても初期化し直さない。
            if (ReferenceEquals(currentAction, nextAction))
            {
                return true;
            }

            if (IsOnCooldown(id))
            {
                return false;
            }

            if (!forceInterrupt && !CanInterruptCurrent)
            {
                return false;
            }

            isProcessing = true;

            try
            {
                // 新しい行動の開始条件を先に確認する。
                if (!nextAction.CanEnter(context))
                {
                    return false;
                }

                if (currentAction != null)
                {
                    EndCurrentAction(
                        context,
                        AgentActionExitReason.Interrupted);
                }

                currentAction = nextAction;
                actionElapsedTime = 0d;

                try
                {
                    currentAction.Enter(context);
                }
                catch (Exception exception)
                {
                    HandleActionFault(context, exception);

                    throw;
                }

                ActionStarted?.Invoke(id);

                return true;
            }
            finally
            {
                isProcessing = false;
            }
        }

        /// <summary>
        /// 時間と実行中の行動を更新する。
        /// </summary>
        /// <param name="context">行動実行情報</param>
        /// <param name="deltaTime">経過秒数</param>
        public void Tick(
            TContext context,
            float deltaTime)
        {
            EnsureNotProcessing();

            if (float.IsNaN(deltaTime) ||
                float.IsInfinity(deltaTime) ||
                deltaTime < 0f)
            {
                throw new ArgumentOutOfRangeException(
                    nameof(deltaTime));
            }

            if (isPaused || deltaTime == 0f)
            {
                return;
            }

            // 行動が存在しなくてもクールダウンを進める。
            totalElapsedTime += deltaTime;

            if (currentAction == null)
            {
                return;
            }

            actionElapsedTime += deltaTime;

            isProcessing = true;

            try
            {
                AgentActionStatus status;

                try
                {
                    status = currentAction.Tick(
                        context, deltaTime);

                    if (status != AgentActionStatus.Running &&
                        status != AgentActionStatus.Succeeded &&
                        status != AgentActionStatus.Failed)
                    {
                        throw new InvalidOperationException(
                            "不正な行動更新結果です。");
                    }
                }
                catch (Exception exception)
                {
                    HandleActionFault(context, exception);

                    throw;
                }

                switch (status)
                {
                    case AgentActionStatus.Succeeded:

                        EndCurrentAction(
                            context,
                            AgentActionExitReason.Succeeded);

                        break;

                    case AgentActionStatus.Failed:

                        EndCurrentAction(
                            context,
                            AgentActionExitReason.Failed);

                        break;
                }
            }
            finally
            {
                isProcessing = false;
            }
        }

        /// <summary>
        /// 現在の行動を外部要求によって停止する。
        /// </summary>
        /// <param name="context">行動実行情報</param>
        /// <returns>停止した行動が存在する場合はtrue</returns>
        /// <remarks>
        /// 最低継続時間や一時停止状態に関係なく停止する。
        /// </remarks>
        public bool Stop(TContext context)
        {
            EnsureNotProcessing();

            if (currentAction == null)
            {
                return false;
            }

            isProcessing = true;

            try
            {
                EndCurrentAction(
                    context,
                    AgentActionExitReason.Cancelled);

                return true;
            }
            finally
            {
                isProcessing = false;
            }
        }

        /// <summary>
        /// 一時停止状態を変更する。
        /// </summary>
        /// <param name="paused">一時停止する場合はtrue</param>
        public void SetPaused(bool paused)
        {
            EnsureNotProcessing();

            isPaused = paused;
        }

        /// <summary>
        /// すべてのクールダウンを解除する。
        /// </summary>
        public void ClearCooldowns()
        {
            EnsureNotProcessing();

            cooldownEndTimes.Clear();
        }

        /// <summary>
        /// 行動を停止し、実行状態と時間を初期化する。
        /// </summary>
        /// <param name="context">行動実行情報</param>
        /// <remarks>
        /// 登録された行動は維持する。
        /// </remarks>
        public void Reset(TContext context)
        {
            EnsureNotProcessing();

            try
            {
                Stop(context);
            }
            finally
            {
                cooldownEndTimes.Clear();

                totalElapsedTime = 0d;
                actionElapsedTime = 0d;

                isPaused = false;
            }
        }

        /// <summary>
        /// 現在の行動を終了する。
        /// </summary>
        /// <param name="context">行動実行情報</param>
        /// <param name="reason">行動終了理由</param>
        private void EndCurrentAction(
            TContext context,
            AgentActionExitReason reason)
        {
            var endedAction = currentAction;

            if (endedAction == null)
            {
                return;
            }

            // 後処理で例外が発生しても実行状態を残さない。
            currentAction = null;
            actionElapsedTime = 0d;

            if (endedAction.Settings.Cooldown > 0f)
            {
                cooldownEndTimes[endedAction.Id] =
                    totalElapsedTime +
                    endedAction.Settings.Cooldown;
            }

            endedAction.Exit(context, reason);

            ActionEnded?.Invoke(endedAction.Id, reason);
        }

        /// <summary>
        /// 行動処理中の例外に対する終了処理を実行する。
        /// </summary>
        /// <param name="context">行動実行情報</param>
        /// <param name="originalException">元の例外</param>
        private void HandleActionFault(
            TContext context,
            Exception originalException)
        {
            try
            {
                EndCurrentAction(
                    context,
                    AgentActionExitReason.Faulted);
            }
            catch (Exception cleanupException)
            {
                // 元の例外と終了処理の例外を両方保持する。
                throw new AggregateException(
                    originalException,
                    cleanupException);
            }
        }

        /// <summary>
        /// 行動処理中の再入操作を防止する。
        /// </summary>
        /// <exception cref="InvalidOperationException">
        /// 行動処理中に変更操作が呼び出された場合に発生する。
        /// </exception>
        private void EnsureNotProcessing()
        {
            if (isProcessing)
            {
                throw new InvalidOperationException(
                    "行動処理中はこの操作を実行できません。");
            }
        }
    }
}
